//! Compiles the `rust` fences of `docs/orm.md` on SQLite. The fences live in
//! `docs_compile/orm_blocks.rs`, generated by `docs_compile.rs`.

#![cfg(all(feature = "sqlite", feature = "tenancy"))]
#![allow(unused, unreachable_code, dead_code, clippy::all)]

/// What the page assumes is in scope: the guide's models and a pool.
mod prelude {
    pub use chrono::{DateTime, Utc};
    pub use rustango::core::Column as _;
    pub use rustango::sql::{Auto, FetcherPool as _, Pool};
    pub use rustango::Model;

    pub type BoxError = Box<dyn std::error::Error>;

    #[derive(Model, Debug, Clone)]
    #[rustango(table = "dc_author")]
    pub struct Author {
        #[rustango(primary_key)]
        pub id: Auto<i64>,
        #[rustango(max_length = 80)]
        pub name: String,
    }

    #[derive(Model, Debug, Clone)]
    #[rustango(table = "dc_post")]
    pub struct Post {
        #[rustango(primary_key)]
        pub id: Auto<i64>,
        #[rustango(max_length = 200)]
        pub title: String,
        #[rustango(max_length = 200)]
        pub slug: String,
        #[rustango(max_length = 20)]
        pub status: String,
        pub author_id: i64,
        pub view_count: i64,
        pub views: i64,
        pub score: Option<i64>,
        pub published: bool,
        pub is_active: bool,
        pub published_at: Option<DateTime<Utc>>,
        pub deleted_at: Option<DateTime<Utc>>,
        pub created_at: DateTime<Utc>,
    }

    #[derive(Model, Debug, Clone)]
    #[rustango(table = "dc_book")]
    pub struct Book {
        #[rustango(primary_key)]
        pub id: Auto<i64>,
        #[rustango(max_length = 200)]
        pub title: String,
        #[rustango(max_length = 20)]
        pub isbn: String,
        #[rustango(max_length = 20)]
        pub status: String,
        pub pages: i64,
        pub author_id: i64,
    }

    #[derive(Model, Debug, Clone)]
    #[rustango(table = "dc_user")]
    pub struct User {
        #[rustango(primary_key)]
        pub id: Auto<i64>,
        #[rustango(max_length = 80)]
        pub name: String,
        #[rustango(max_length = 200)]
        pub email_norm: String,
    }
}

#[rustfmt::skip]
#[path = "docs_compile/orm_blocks.rs"]
mod blocks;

#[test]
fn the_orm_page_compiles() {}
